<?php
require_once __DIR__.'/bootstrap.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='GET'){api_response(['data'=>$pdo->query('SELECT t.id,t.name,t.code,t.description,t.content,d.name type_name FROM document_templates t JOIN document_types d ON d.id=t.document_type_id WHERE t.is_active=1 ORDER BY t.name')->fetchAll()]);}if(!in_array(current_user()['role_name'],['ADMIN','HR'],true))api_response(['error'=>'HR authorization required.'],403);verify_csrf();$input=api_input();foreach(['document_type_id','name','code','content'] as $field)if(empty($input[$field]))api_response(['error'=>$field.' is required.'],422);try{$pdo->prepare('INSERT INTO document_templates (document_type_id,name,code,description,content,created_by) VALUES (?,?,?,?,?,?)')->execute([$input['document_type_id'],$input['name'],$input['code'],$input['description']??null,$input['content'],$_SESSION['user_id']]);api_response(['data'=>['id'=>(int)$pdo->lastInsertId()]],201);}catch(PDOException $exception){api_response(['error'=>'Template code already exists.'],422);}